pub fn makeRetry(comptime has_retry: bool, comptime ErrorType: type, comptime T: type) T {
        if (has_retry) {
            return .{ .err = ErrorType.retry };
        }
        return .{ .err = .{} };
}

pub fn makeSuccess(comptime ReturnType: type, comptime T: type) T {
        return .{ .result = std.mem.zeroes(ReturnType) };
}

pub fn makeAborted(comptime T: type) T {
        return .{ .err = .{ .errno = @intFromEnum(posix.E.INTR), .syscall = .access } };
}

pub fn Maybe(comptime ReturnTypeT: type, comptime ErrorTypeT: type) type {
        const has_any_decls = ((ErrorTypeT != void) and (ErrorTypeT != AnyError));
        const has_retry = (has_any_decls and @hasDecl(ErrorTypeT, "retry"));
        const has_todo = (has_any_decls and @hasDecl(ErrorTypeT, "todo"));
        return union(MaybeTag) {
    err: ErrorType,
    result: ReturnType,

pub inline fn todo() @This() {
            if (Environment.allow_assert) {
                if (comptime (ReturnType == void)) {
                    _ = @panic("TODO called!");
                }
                _ = @panic((comptime (("TODO: Maybe(" ++ bun.meta.typeName(ReturnType)) ++ ")")));
            }
            if (has_todo) {
                return .{ .err = ErrorType.todo() };
            }
            return .{ .err = ErrorType{  } };
    }

pub fn isTrue(self: @This()) bool {
            if (comptime (ReturnType != bool)) {
                _ = @compileError("This function can only be called on bool");
            }
            return (switch (self) {
.result => |r| r,
else => false,
});
    }

pub fn unwrap(self: @This()) anyerror!ReturnType {
            return (switch (self) {
.result => |r| r,
.err => |e| bun.errnoToZigErr(e.errno),
});
    }

pub inline fn unwrapOr(self: @This(), default_value: ReturnType) ReturnType {
            return (switch (self) {
.result => |v| v,
.err => default_value,
});
    }

pub inline fn initErr(e: ErrorType) Maybe(ReturnType, ErrorType) {
            return .{ .err = e };
    }

pub inline fn initErrWithP(e: bun.sys.SystemErrno, syscall: sys.Tag, file_path: anytype) Maybe(ReturnType, ErrorType) {
            return .{ .err = .{ .errno = @intFromEnum(e), .syscall = syscall, .path = file_path } };
    }

pub inline fn asErr(self: *const @This()) ?ErrorType {
            if ((self.* == .err)) {
                return self.err;
            }
            return null;
    }

pub inline fn asValue(self: *const @This()) ?ReturnType {
            if ((self.* == .result)) {
                return self.result;
            }
            return null;
    }

pub inline fn isOk(self: *const @This()) bool {
            return (switch (self.*) {
.result => true,
.err => false,
});
    }

pub inline fn isErr(self: *const @This()) bool {
            return (switch (self.*) {
.result => false,
.err => true,
});
    }

pub inline fn initResult(res: ReturnType) Maybe(ReturnType, ErrorType) {
            return .{ .result = res };
    }

pub inline fn mapErr(self: @This(), comptime E: type, err_fn: *const fn (ErrorTypeT) E) Maybe(ReturnType, E) {
            return (switch (self) {
.result => |v| .{ .result = v },
.err => |e| .{ .err = err_fn(e) },
});
    }

