pub fn toJS(self: @This(), globalObject: *jsc.JSGlobalObject) bun.JSError!jsc.JSValue {
            return (switch (self) {
.result => |r| (if (ReturnType == jsc.JSValue) r else if (ReturnType == void) .js_undefined else if (ReturnType == bool) jsc.JSValue.jsBoolean(r) else if (ReturnType == jsc.ArrayBuffer) r.toJS(globalObject) else if (ReturnType == []u8) jsc.ArrayBuffer.fromBytes(r, .ArrayBuffer).toJS(globalObject) else (switch (@typeInfo(ReturnType)) {
