                    _ = jsc.ZigString.init(bun.asByteSlice(r)).withEncoding().toJS(globalObject);
                }
                return r.toJS(globalObject);
            }
},
})),
.err => |e| e.toJS(globalObject),
});
    }

pub fn toArrayBuffer(self: @This(), globalObject: *jsc.JSGlobalObject) jsc.JSValue {
            return (switch (self) {
.result => |r| jsc.ArrayBuffer.fromBytes(r, .ArrayBuffer).toJS(globalObject, null),
.err => |e| e.toJS(globalObject),
});
    }

pub fn getErrno(self: @This()) posix.E {
            return (switch (self) {
.result => posix.E.SUCCESS,
.err => |e| @enumFromInt(e.errno),
});
    }

pub fn errnoSys(rc: anytype, syscall: sys.Tag) ?@This() {
            if (comptime Environment.isWindows) {
                if (comptime (@TypeOf(rc) == std.os.windows.NTSTATUS)) {
                } else {
                    if ((rc != 0)) {
                        return null;
                    }
                }
            }
            return (switch (sys.getErrno(rc)) {
.SUCCESS => null,
else => |e| @This(){ .err = .{ .errno = translateToErrInt(e), .syscall = syscall } },
});
    }

pub fn errno(e: anytype, syscall: sys.Tag) @This() {
            return @This(){ .err = .{ .errno = translateToErrInt(e), .syscall = syscall } };
    }

