pub fn format(self: @This(), writer: *std.Io.Writer) !void {
            return (switch (self) {
.result => try writer.print("Result(...)", .{}),
.err => |e| try writer.print((("Error(" ++ bun.deprecated.autoFormatLabelFallback(ErrorType, "{any}")) ++ ")"), .{ e }),
});
    }
    pub const ErrorType = ErrorTypeT;
