pub fn translateToErrInt(e: anytype) bun.sys.Error.Int {
        if (comptime (@TypeOf(e) == bun.windows.NTSTATUS)) {
            return @intFromEnum(bun.windows.translateNTStatusToErrno(e));
        }
        return @truncate(@intFromEnum(e));
}
